from sage.all_cmdline import *   # import sage library

_sage_const_0p25 = RealNumber('0.25'); _sage_const_0p5 = RealNumber('0.5'); _sage_const_0p125 = RealNumber('0.125'); _sage_const_0p0625 = RealNumber('0.0625'); _sage_const_0p2 = RealNumber('0.2'); _sage_const_1 = Integer(1); _sage_const_0 = Integer(0); _sage_const_8 = Integer(8)# -----------------------------------------------------------------------------
# example_StC_CtS.sage
#
# Test generation and use of true CKKS bootstrapping CoeffToSlot and SlotToCoeff
# diagonals in the ModHE / MLWE-CKKS Sage prototype.
#
# This version tests the bootstrap-style two-ciphertext flow:
#
#     native CKKS slot ciphertext
#         -> CoeffToSlot
#              ct_lo encrypts coefficient slots (t0, ..., t_{N/2-1})
#              ct_hi encrypts coefficient slots (t_{N/2}, ..., t_{N-1})
#         -> SlotToCoeff
#              one ciphertext encrypting the reconstructed polynomial
#
# For first debugging, use small POLDEG in constants.sage, e.g. 8, 16, or 32.
# Diagonal generation is still a correctness/reference implementation and is not
# optimized for POLDEG = 2^14.
# -----------------------------------------------------------------------------

load("constants.sage")
load("auxiliary_functions.sage")
load("KeyGen.sage")
load("Encrypt-Decrypt.sage")
load("encode.sage")
load("encode-encrypt.sage")
load("HMult.sage")
load("Relin.sage")
load("bootstrap_keys.sage")
load("bootstrap_ops.sage")
load("linear_transform.sage")

print("POLDEG=", POLDEG, "slots=", ckks_num_slots(), "MLWE=", MLWE)
print("This example is intended for small POLDEG first.")
print("Testing true bootstrap-style two-ciphertext CoeffToSlot/SlotToCoeff.")


# -----------------------------------------------------------------------------
# 1. Test slots.
# -----------------------------------------------------------------------------
slots = [
    CCK(_sage_const_0p25 ),
    CCK(-_sage_const_0p5 ) + CCK(_sage_const_0p125 )*CCK(I),
    CCK(_sage_const_0p0625 ) - CCK(_sage_const_0p2 )*CCK(I)
]


# -----------------------------------------------------------------------------
# 2. Cleartext check of the mathematical maps.
# -----------------------------------------------------------------------------
print("\n[cleartext true bootstrap CoeffToSlot -> SlotToCoeff self-test]")
ckks_bootstrap_c2s_s2c_clear_selftest(slots)


# -----------------------------------------------------------------------------
# 3. Generate true bootstrap plaintext diagonals for CoeffToSlot and SlotToCoeff.
# -----------------------------------------------------------------------------
print("\n[generating true bootstrap CoeffToSlot diagonals]")
c2s_boot_diags = generate_coeff_to_slot_bootstrap_diagonals(
    diag_scale=p_enc,
    factor=_sage_const_1 ,
    method="fft"
)

print("C2S lo A diagonals=", len(c2s_boot_diags["lo"]["A"]),
      "lo B diagonals=", len(c2s_boot_diags["lo"]["B"]))
print("C2S hi A diagonals=", len(c2s_boot_diags["hi"]["A"]),
      "hi B diagonals=", len(c2s_boot_diags["hi"]["B"]))


print("\n[generating true bootstrap SlotToCoeff diagonals]")
s2c_boot_diags = generate_slot_to_coeff_bootstrap_diagonals(
    diag_scale=p_enc,
    factor=_sage_const_1 ,
    method="fft"
)

print("S2C lo A diagonals=", len(s2c_boot_diags["lo"]["A"]),
      "lo B diagonals=", len(s2c_boot_diags["lo"]["B"]))
print("S2C hi A diagonals=", len(s2c_boot_diags["hi"]["A"]),
      "hi B diagonals=", len(s2c_boot_diags["hi"]["B"]))


# Collect all rotation exponents from the nested lo/hi, A/B diagonal bundles.
rot_exps = merge_rotation_exponents_deep(c2s_boot_diags, s2c_boot_diags)
print("rotation exponents needed=", len(rot_exps))
print("rotation exponents=", rot_exps)


# -----------------------------------------------------------------------------
# 4. Key generation.
# -----------------------------------------------------------------------------
print("\n[key generation]")
key = public_private_keygen()

# For this C2S/S2C test, we need rotation keys and conjugation key.
# We do not need relinearization because this test only uses linear transforms:
# rotations, conjugation, plaintext multiplications, and additions.
boot_keys = boot_keygen(
    key,
    rotation_exponents=rot_exps,
    include_relin=False
)


# -----------------------------------------------------------------------------
# 5. Encrypt original CKKS slots.
# -----------------------------------------------------------------------------
print("\n[encrypt original CKKS slots]")
ct = encryption_ckks(slots, key, p_enc, method="fft")

print("decrypt original:")
orig = decryption_ckks(
    ct,
    key,
    _sage_const_0 ,
    _sage_const_0 ,
    p_enc,
    len(slots),
    method="fft"
)

for i in range(len(slots)):
    print(i, "in=", slots[i], "dec=", orig[i], "err=", abs(orig[i] - slots[i]))


# -----------------------------------------------------------------------------
# 6. Homomorphic true bootstrap CoeffToSlot.
# -----------------------------------------------------------------------------
print("\n[homomorphic true bootstrap CoeffToSlot]")
print("Expected output:")
print("  ct_lo encrypts coefficient slots (t0, ..., t_{N/2-1})")
print("  ct_hi encrypts coefficient slots (t_{N/2}, ..., t_{N-1})")

ct_lo, ct_hi = coeff_to_slot_bootstrap_two_ct(
    ct,
    c2s_boot_diags,
    boot_keys,
    divide_by_diag_scale=True
)


# Optional debugging: decrypt ct_lo and ct_hi as CKKS slot ciphertexts.
# These are not supposed to equal the original input slots.
# They should contain the two halves of the plaintext polynomial coefficients.
print("\n[debug: decrypt CoeffToSlot outputs]")
lo_slots = decryption_ckks(
    ct_lo,
    key,
    _sage_const_0 ,
    _sage_const_0 ,
    p_enc,
    ckks_num_slots(),
    method="fft"
)

hi_slots = decryption_ckks(
    ct_hi,
    key,
    _sage_const_0 ,
    _sage_const_0 ,
    p_enc,
    ckks_num_slots(),
    method="fft"
)

print("ct_lo first slots:")
for i in range(min(_sage_const_8 , ckks_num_slots())):
    print("lo", i, "=", lo_slots[i])

print("ct_hi first slots:")
for i in range(min(_sage_const_8 , ckks_num_slots())):
    print("hi", i, "=", hi_slots[i])


# -----------------------------------------------------------------------------
# 7. Homomorphic true bootstrap SlotToCoeff.
# -----------------------------------------------------------------------------
print("\n[homomorphic true bootstrap SlotToCoeff]")
print("Merging ct_lo and ct_hi back into one native CKKS polynomial ciphertext.")

ct_back = slot_to_coeff_bootstrap_two_ct(
    ct_lo,
    ct_hi,
    s2c_boot_diags,
    boot_keys,
    divide_by_diag_scale=True
)


# -----------------------------------------------------------------------------
# 8. Decrypt/decode roundtrip result.
# -----------------------------------------------------------------------------
print("\n[roundtrip result: original slots -> C2S split -> S2C merge -> slots]")
out = decryption_ckks(
    ct_back,
    key,
    _sage_const_0 ,
    _sage_const_0 ,
    p_enc,
    len(slots),
    method="fft"
)

max_err = _sage_const_0 
for i in range(len(slots)):
    err = abs(out[i] - slots[i])
    max_err = max(max_err, err)
    print(i, "in=", slots[i], "out=", out[i], "err=", err)

print("max roundtrip err=", max_err)


# -----------------------------------------------------------------------------
# 9. Notes.
# -----------------------------------------------------------------------------
print("\nNOTE:")
print("This validates only the two-ciphertext bootstrap CoeffToSlot/SlotToCoeff")
print("linear-transform wiring.")
print("")
print("It does NOT yet test:")
print("  - ModRaise")
print("  - EvalExp / EvalMod")
print("  - ImgExt")
print("  - CKKS scale/rescale/level management")
print("  - optimized Cooley-Tukey or BSGS DFT decomposition")
print("")
print("The divide_by_diag_scale=True option is still a prototype correction using")
print("modular inverses. A production CKKS bootstrap should replace this with")
print("proper plaintext-ciphertext multiplication scale tracking and rescaling.")









